                textDecoration: item.done ? 'line-through' : 'none',
              }}
            >
              <span>{item.done ? '✓' : '○'}</span>
              {item.t}
            </div>
          ))}
        </div>
      );
    case 'table':
      return (
        <div style={{ padding: 8, fontSize: 13 }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid var(--g-color-line-generic)' }}>
